// Regenerates browser_sources.mjs, the Worker-importable module carrying the
// TEMPORARY staging fixture's browser sources. check_page.test.mjs fails on
// any drift, so a stale generated file never ships silently.
//   node cloud/library/sync_check_page.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
const here = fileURLToPath(new URL('.', import.meta.url));
const entries = [
  ['/v1/service-check/browser/app.js', 'browser/app.js', 'text/javascript; charset=utf-8'],
  ['/v1/service-check/browser/check_core.mjs', 'check_core.mjs', 'text/javascript; charset=utf-8'],
  ['/v1/service-check/browser/schema.mjs', 'schema.mjs', 'text/javascript; charset=utf-8'],
  ['/v1/service-check/browser/part.mjs', 'part.mjs', 'text/javascript; charset=utf-8'],
  ['/v1/service-check/browser/fields.json', 'fields.json', 'application/json; charset=utf-8'],
];
let out = `// GENERATED by sync_check_page.mjs from the canonical sources. Do not edit by
// hand; check_page.test.mjs verifies this file is fresh. TEMPORARY staging
// fixture content, removed with the fixture route once the gates pass.
export const CHECK_ASSETS = {
`;
for (const [route, file, type] of entries) {
  // LF-normalize so a CRLF checkout (Windows) yields the same generated module;
// the freshness guarantee covers real content drift, not checkout mangling.
const sourceText = file => readFileSync(here + file, 'utf8').replace(/\r\n/g, '\n');
out += `  ${JSON.stringify(route)}: [${JSON.stringify(sourceText(file))}, ${JSON.stringify(type)}],\n`;
}
out += '};\n';
if (process.argv.includes('--check')) {
  const current = readFileSync(here + 'browser_sources.mjs', 'utf8');
  if (current !== out) {
    console.error('browser_sources.mjs is stale; run node sync_check_page.mjs');
    process.exit(1);
  }
  console.log('browser_sources.mjs is fresh');
} else {
  writeFileSync(here + 'browser_sources.mjs', out);
  console.log('browser_sources.mjs regenerated');
}
